if constexpr (PAD_M)
return make_gmem(ptr, static_cast<unsigned int>((kargs.m - row) * kargs.stride_a));
else
return make_gmem(ptr);
}();
auto g_b = make_gmem(reinterpret_cast<const D_B*>(kargs.ptr_b) + batch_id * kargs.stride_b_batch + col * kargs.stride_b);
auto g_c = [&] {
auto ptr = reinterpret_cast<D_C*>(kargs.ptr_c) + batch_id * kargs.stride_c_batch + row * kargs.stride_c + col;
if constexpr (PAD_M)
return make_gmem(ptr, static_cast<unsigned int>(((kargs.m - row) * kargs.stride_c - col) * sizeof(D_C)));
else
return make_gmem(ptr);
}();
