auto* a1_chunks = reinterpret_cast<AChunk*>(&v_a[1]);
auto* b0_chunks = reinterpret_cast<BChunk*>(&v_b);
auto* b1_chunks = reinterpret_cast<BChunk*>(&v_b_second);
