s_waitcnt_lgkmcnt(0_I);
__builtin_amdgcn_s_barrier();
load_sfa_panel(next_tile);
D_SF_PACK raw_b = 0;
if (wave_id < T::SCALE_N_HALVES && lane_id < T::SCALE_PANEL_K_CAPACITY) {
