load_sfa_panel(0);
D_SF_PACK panel_sfb_raw = 0;
if (wave_id < T::SCALE_N_HALVES && lane_id < T::SCALE_PANEL_K_CAPACITY) {
const auto raw = load<1>(g_sfb, u_gsfb + gsfb_offset(0));
panel_sfb_raw = static_cast<D_SF_PACK>(raw[0]);
