async_load<T::VEC_B>(g_b, s_b.ptr, u_gb, u_sb + sb_offset(0, 0), gb_offset(0, 0));
async_load<T::VEC_B>(g_b, s_b.ptr, u_gb, u_sb + sb_offset(0, 1), gb_offset(1, 0));
publish_sfa_panel(0);
if (wave_id < T::SCALE_N_HALVES && lane_id < T::SCALE_PANEL_K_CAPACITY) {
