};
auto advance_tile = [&](auto stage_i, int tile_k) {
constexpr int stage = decltype(stage_i)::value;
constexpr int next_stage = (stage + 1) % T::NUM_STAGES;
read_scales(tile_k + 1, v_sfa_next, v_sfb_next);
