seq<T::E_M, T::E_N, T::E_K>{},
seq<T::T_M, T::T_N, T::T_K>{},
seq<T::W_M, T::W_N, T::W_K>{},
mfma_adaptor_swap_ab{});
constexpr int ELEM_A = decltype(mma)::elem_a;
constexpr int ELEM_B = decltype(mma)::elem_b;
