if constexpr (decltype(m_i)::value == 0) {
__builtin_amdgcn_sched_barrier(0);
s_waitcnt_vmcnt(0_I);
s_waitcnt_lgkmcnt(0_I);
__builtin_amdgcn_s_barrier();
if (tile_k + 2 < loops)
