constexpr int k_per_wave_load = lanes_k * T::VEC_B;
constexpr int n_repeats = T::HALF_B_N / (T::NUM_WAVES * lanes_n);
constexpr int k_repeats = T::B_K / k_per_wave_load;
constexpr auto gb_block_shape = opus::make_tuple(
opus::number<T::T_N>{},
opus::number<T::T_M>{},
