async_load<16>(g_a, s_a.ptr, u_ga, u_sa + slot * T::A_STAGE, group * T::B_K);
static_for<2>([&](auto pass) {
const int ng = wave_id + decltype(pass)::value * T::NUM_WAVES;
if (ng < T::B_N / T::W_N) {
static_for<2>([&](auto half) {
constexpr int h = decltype(half)::value;
