};
load_scale_panel();
issue_matrix_prefetch(number<0>{}, number<0>{});
if (loops > 1) issue_matrix_prefetch(number<1>{}, number<1>{});
s_waitcnt_vmcnt(0_I);
s_waitcnt_lgkmcnt(0_I);
__builtin_amdgcn_s_barrier();
